+        </select>
+      </div>
+      <div>
+        <label for="until">Until (optional)</label>
+        <input id="until" type="date" />
+      </div>
+    </div>
+
+    <button id="generate-btn">Generate</button>
+    <div id="status"></div>
+  </div>
+
+  <!-- Results -->
+  <div id="results" class="hidden">
+
+    <!-- Before / After -->
+    <div class="card">
+      <h2>Before vs. After</h2>
+      <div class="before-after">
+        <div class="panel-box">
+          <h3>Raw git log</h3>
+          <pre id="raw-log"></pre>
+        </div>
+        <div class="panel-box">
+          <h3>Generated summary</h3>
+          <pre id="summary-preview"></pre>
+        </div>
+      </div>
+    </div>
+
+    <!-- Blockers -->
+    <div id="blockers-section" class="hidden card">
+      <h2>⚠️ Possible Blockers</h2>
+      <ul id="blockers-list"></ul>
+    </div>
+
+    <!-- Format outputs -->
+    <div class="card">
+      <h2>Output Formats</h2>
+      <div class="tabs">
+        <button class="tab-btn active" data-tab="slack">Slack</button>
+        <button class="tab-btn" data-tab="email">Email</button>
+        <button class="tab-btn" data-tab="standup">Standup</button>
+      </div>
+
+      <div id="tab-slack" class="tab-panel active">
+        <button class="copy-btn" onclick="copyTab('slack')">Copy</button>
+        <pre id="output-slack"></pre>
+      </div>
+      <div id="tab-email" class="tab-panel">
+        <button class="copy-btn" onclick="copyTab('email')">Copy</button>
+        <pre id="output-email"></pre>
+      </div>
+      <div id="tab-standup" class="tab-panel">
+        <button class="copy-btn" onclick="copyTab('standup')">Copy</button>
+        <pre id="output-standup"></pre>
+      </div>
+    </div>
+
+  </div>
